<?php namespace App\Filament\Resources\StudentAchievementResource\Pages;use App\Filament\Resources\StudentAchievementResource;use App\Services\PeriodGuard;use Filament\Resources\Pages\CreateRecord;class CreateStudentAchievement extends CreateRecord{protected static string $resource=StudentAchievementResource::class;protected function mutateFormDataBeforeCreate(array $d):array{$p=request()->attributes->get('academic_period');if($p){PeriodGuard::writable($p->id);$d['academic_period_id']=$p->id;}return $d;}}